using System;
using System.Linq;
using UnityEngine;
namespace BWVR.Editor {
public static class BowlCreatureTurnChecks {
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){var p=new BuildBowlProject();Check(p.Valid()&&!p.RecordCreatureTurn(0,true),"Old save granted turn");p.Begin(1,0);p.Confirm(true,false,1,true,false);Check(!p.RecordCreatureTurn(1,true),"Unreturned shot granted creature turn");p.RecordReturn(1);Check(p.RecordCreatureTurn(1,true)&&!p.RecordCreatureTurn(1,true)&&p.creatureShots==1&&p.creatureHits==1&&!p.creatureHit&&p.shots==1&&p.phase==GatewayPhase.Active&&p.Valid(),"Creature turn duplicated or completed player objective");Check(JsonUtility.FromJson<BuildBowlProject>(JsonUtility.ToJson(p)).Valid(),"Creature result did not save");p.Begin(1,2);Check(p.creatureShots==1,"Active attempt restarted");p.End();p.Begin(1,3);Check(p.creatureShots==0&&p.creatureHits==0&&p.lastCreatureTurn==0&&p.Valid(),"Replay retained previous turn");Debug.Log("BWVR_CREATURE_COURSE_MODEL_PASS: legacy saves, physical-return prerequisite, disjoint player/creature outcomes, one-turn guard, persistence and replay");}
 public static void Verify(bool harmful=false,bool cancel=false){BowlRebuildChecks.Verify(null,(slice,ball,site,block)=>{
  var god=slice.GetComponentInChildren<CreatureHybrid>();var mind=god.GetComponent<CreatureCuriosity>();var state=god.Season;var p=state.buildBowl;int playerShots=p.shots;bool playerHit=p.playerHit,creaturePieceHit=p.creatureHit;Check(ball.BowlTurnOffered&&ball.TryBowlTurnStance(out _),"Fresh witnessed rebuild did not offer safe creature turn");Check(!ball.BuildBowlPending&&p.creatureShots==0,"Offer counted an outcome");bool approach=false,lift=false;for(int i=0;i<2600&&!ball.BowlCreaturePending;i++){god.Tick(.05f);ball.Advance(.05f,false);site.Advance(.02f);approach|=mind.Current==CreatureCuriosity.Phase.BowlTurnApproach;lift|=mind.Current==CreatureCuriosity.Phase.Lift;if(cancel&&mind.Current==CreatureCuriosity.Phase.BowlTurnApproach){ball.CancelCourseShot();god.Tick(.05f);ball.Advance(.05f,false);Check(!ball.GetComponent<CarryItem>().held&&!ball.BowlCreaturePending&&p.creatureShots==0&&p.creatureHits==0&&p.shots==playerShots,"Canceled carry stranded ball or scored");ball.ReturnHome();Debug.Log("BWVR_CREATURE_COURSE_CANCEL_PASS: native lift/carry canceled through course reset, released physical ownership, no fallback roll or project reward");return;}}
  Check(lift&&approach&&ball.BowlCreaturePending&&state.WorldPlay.throws>0,"Native chooser/lift/approach/roll did not launch: "+mind.Current+" / "+god.Explanation);var position=ball.Body.position;state.paused=true;ball.Advance(2,true);god.Tick(2);Check(ball.BowlCreaturePending&&position==ball.Body.position&&p.creatureShots==0,"Paused roll moved or scored");state.paused=false;
  for(int i=0;i<200&&block.Attached&&ball.BowlCreaturePending;i++){god.Tick(.02f);ball.Advance(.02f,false);site.Advance(.02f);}Check(!block.Attached&&ball.BowlCreaturePending&&p.creatureShots==0,"Real roll did not detach rebuilt player target");ball.Body.linearVelocity=ball.Body.angularVelocity=Vector3.zero;
  if(harmful)ball.Impact(slice.GetComponentsInChildren<PlayImpactTarget>().First(t=>t.kind=="villager"),12);
  for(int i=0;i<700&&(ball.BowlCreaturePending||god.Owner!=CreatureHybrid.ActionOwner.None);i++){god.Tick(.02f);ball.Advance(.02f,false);site.Advance(.02f);}
  Check(!ball.BowlCreaturePending&&!site.BuildBowlReserved&&p.shots==playerShots&&p.playerHit==playerHit&&p.creatureHit==creaturePieceHit,"Creature turn changed player objectives or stranded yard");
  if(harmful)Check(p.creatureShots==0&&p.creatureHits==0,"Harmful shot received project credit");else{Check(p.creatureShots==1&&p.creatureHits==1&&p.lastCreatureTurn==p.lastReturnedShot&&state.Hybrid.receipt.eligible&&state.Hybrid.receipt.action==CreatureAction.PlayWithToy,"Safe physical creature result or native lesson missing");Check(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(state)).Valid(),"Safe turn save invalid");}
  ball.ReturnHome();Debug.Log(harmful?"BWVR_CREATURE_COURSE_HARM_PASS: actual creature roll/contact, injected late native villager harm withheld project credit, no player progress, physical cleanup":"BWVR_CREATURE_COURSE_RUNTIME_PASS: real player rebuild after native return, autonomous selection, lift/carry to safe stance, real roll and target detach, pause and 12-second confirmation, distinct saved creature outcome and native action lesson");
 });}
}
}
